description:
Design a 32-bit Arithmetic Logic Unit (ALU) that performs various arithmetic and logic operations based on a 6-bit operation code (op). The ALU takes two 32-bit inputs and, depending on the value of op, can execute operations such as addition, subtraction, bitwise operations (AND, OR, XOR), shifts (logical and arithmetic), comparisons, and checking equality or inequality. The result of the selected operation is output as a 32-bit value. If the operation code does not match any specified case, the output defaults to zero.
module top_module(
    in1, in2, op, out
);

code:
module top_module(
    in1, in2, op, out
);input wire [31:0] in1, in2;
    input wire [5:0] op;
    output reg [31:0] out;

    always @(*) begin
        case(op)
				1: out <= in1+in2;							
				2: out <= in1-in2;							
				3: out <= in1&in2;							
				4: out <= in1|in2;							
				5: out <= in1^in2;							
				6: out <= in1<<in2[4:0];					
				7: out <= in1>>in2[4:0];					
				8: out <= $signed(in1)>>>in2[4:0];			
				9: out <= ($signed(in1)<$signed(in2))? 1:0;	
				10: out <= (in1<in2)? 1:0;					
				11: out <= (in1==in2) ? 1:0; 					
				12: out <= (in1!=in2) ? 1:0; 					
				13: out <= ($signed(in1)>=$signed(in2))? 1:0;	
				14: out <= (in1>=in2)? 1:0;					
				15: out <= in2;
				default: out <= 0;
		  endcase
    end

endmodule

