function [n-1:0] encrypt;
  input [n-1:0] data;
  input [k-1:0] key;
  begin
    encrypt = data ^ key;
  end
endfunction

function [n-1:0] decrypt;
  input [n-1:0] data;
  input [k-1:0] key;
  begin
    decrypt = data ^ key;
  end
endfunction

assign data_out = (mode == 0) ? encrypt(data_in, key_in) : decrypt(data_in, key_in);

endmodule

