module top_module (
        input clk,
        input reset,
        input x,
        output reg out);parameter A=0, B=1, C=2, D=3;
	reg[1:0] state, next;

	always @(posedge clk)
		if (reset) state <= A;
		else state <= next;


	always_comb begin
		case (state)
			A: next = x ? B : A;
			B: next = x ? C : D;
			C: next = x ? A : D;
			D: next = x ? B : A;
			default: next = 'x;
		endcase
	end

	assign out = (state == B) || (state == C);

endmodule

