description:
Design a rising edge detector that tracks the maximum value from a 3-bit input during the clock cycles. The module latches the current input value into a count register on the rising edge of the clock and maintains a record of the maximum count observed. It determines the index of the input line carrying the maximum value and outputs this value. In essence, the module functions as a single-output selector based on the highest input value observed, effectively prioritizing the largest bit from the input during each clock cycle.
module top_module(
  input  wire       clk,
  input  wire [2:0] in,
  output reg        out
);

code:
module top_module(
  input  wire       clk,
  input  wire [2:0] in,
  output reg        out
);reg [2:0] count;
  reg [2:0] max_count;
  reg        max_input;

  always @(posedge clk) begin
    count <= {in[0], in[1], in[2]};
    if (count > max_count) begin
      max_count <= count;
      max_input <= 0;
    end
    if (count == max_count && in[0] > in[max_input]) begin
      max_input <= 0;
    end
    if (count == max_count && in[1] > in[max_input]) begin
      max_input <= 1;
    end
    if (count == max_count && in[2] > in[max_input]) begin
      max_input <= 2;
    end
  end

  always @(posedge clk) begin
    out <= in[max_input];
  end

endmodule

