module top_module(
    input clk,
    input areset,  // async active-high reset to zero
    input load,
    input ena,
    input [3:0] data,
    input [1:0] edge_detect,
    output reg [3:0] q,
    output reg rise,
    output reg down
);reg [3:0] shift_reg;
reg [3:0] shift_reg_out;
reg [1:0] edge_detect_out;
reg [1:0] edge_detect_out_reg;
reg [1:0] edge_detect_out_reg2;

always @(posedge clk or posedge areset) begin
    if (areset) begin
        shift_reg <= 4'b0;
        q <= 4'b0;
        rise <= 1'b0;
        down <= 1'b0;
        edge_detect_out_reg <= 2'b0;
        edge_detect_out_reg2 <= 2'b0;
    end else begin
        if (load) begin
            shift_reg <= data;
        end else if (ena) begin
            if (edge_detect == 2'b00) begin
                shift_reg <= {shift_reg[2:0], shift_reg[3]};
            end else if (edge_detect == 2'b01) begin
                shift_reg <= {shift_reg[1:0], data};
            end else if (edge_detect == 2'b10) begin
                edge_detect_out_reg <= {shift_reg[0], ~shift_reg[0]};
                edge_detect_out_reg2 <= {edge_detect_out_reg[0], ~edge_detect_out_reg[0]};
                edge_detect_out <= edge_detect_out_reg & edge_detect_out_reg2;
                shift_reg <= {shift_reg[2:0], edge_detect_out[0]};
            end else begin
                shift_reg <= {data, shift_reg[3:1]};
            end
        end
    end
end

always @(posedge clk or posedge areset) begin
    if (areset) begin
        rise <= 1'b0;
        down <= 1'b0;
        shift_reg_out <= 4'b0; // Initialize shift_reg_out on reset
    end else begin
        rise <= shift_reg_out[3] & ~shift_reg[3];
        down <= ~shift_reg_out[3] & shift_reg[3];
        shift_reg_out <= shift_reg;
    end
end

always @(posedge clk) begin
    q <= shift_reg; // Corrected assignment to q
end

endmodule

