module up_down_counter
    (
        input rst_n,
        input clk,
        input up,
        output reg [2:0] count
    );

    always @(posedge clk or negedge rst_n) 
    begin
        if (!rst_n)
            count <= 3'd0;
        else if (up)
            count <= count + 1;
        else
            count <= count - 1;
    end

endmodule

