description:
Design an up-counter that increments its value on each positive clock edge. It has a 3-bit output representing the current count, which resets to zero when the `rst` input signal is high. The counter cycles through values from 0 to 7 and then wraps back to 0, providing a simple binary counting mechanism suitable for applications requiring a limited range of counts.
module top_module(
    input clk,
    input rst,
    output reg [2:0] count
);

code:
module top_module(
    input clk,
    input rst,
    output reg [2:0] count
);reg [2:0] next_count;

always @ (posedge clk) begin
    if (rst) begin
        count <= 3'b0;
    end
    else begin
        count <= next_count;
    end
end

always @ (*) begin
    case (count)
        3'b000: next_count = 3'b001;
        3'b001: next_count = 3'b010;
        3'b010: next_count = 3'b011;
        3'b011: next_count = 3'b100;
        3'b100: next_count = 3'b101;
        3'b101: next_count = 3'b110;
        3'b110: next_count = 3'b111;
        3'b111: next_count = 3'b000;
        default: next_count = 3'b0;
    endcase
end

endmodule

