description:
Design a 4-bit binary adder that takes two 4-bit inputs, A and B, and produces a 4-bit sum output S. The adder implements full-adder logic for each bit, generating a carry output that propagates to the next higher bit. The first bit uses an XOR gate to calculate the sum and an AND gate to detect any carry. This logic is similarly applied for the second through fourth bits, with carry-forward handled through OR operations to aggregate carry outputs from the preceding bits.
module top_module(
    input [3:0] A,
    input [3:0] B,
    output [3:0] S
);

code:
module top_module(
    input [3:0] A,
    input [3:0] B,
    output [3:0] S
);wire [3:0] C;

    // First bit
    xor xor1(S[0], A[0], B[0]);
    and and1(C[0], A[0], B[0]);

    // Second bit
    xor xor2(S[1], A[1], B[1], C[0]);
    and and2(C[1], A[1], B[1]);
    or or1(C[1], C[1], C[0] & A[1] & B[1]);

    // Third bit
    xor xor3(S[2], A[2], B[2], C[1]);
    and and3(C[2], A[2], B[2]);
    or or2(C[2], C[2], C[1] & A[2] & B[2]);

    // Fourth bit
    xor xor4(S[3], A[3], B[3], C[2]);
    and and4(C[3], A[3], B[3]);
    or or3(C[3], C[3], C[2] & A[3] & B[3]);

endmodule

