module top_module(
   input wire clk,
   input wire rst,
   input wire [3:0] in,
   input wire [3:0] cycles,
   output wire [3:0] out
);parameter WIDTH = 4;

   logic [WIDTH-1:0] shift_reg;
   logic [WIDTH-1:0] delayed_reg;
   logic [WIDTH-1:0] cycles_reg;

   always_ff @(posedge clk) begin
      if (rst) begin
         shift_reg <= 0;
         delayed_reg <= 0;
         cycles_reg <= 0;
      end else begin
         shift_reg <= {shift_reg[WIDTH-2:0], in};
         cycles_reg <= cycles;
         if (cycles_reg == 0) begin
            delayed_reg <= shift_reg;
         end else begin
            delayed_reg <= delayed_reg;
            cycles_reg <= cycles_reg - 1;
         end
      end
   end

   assign out = delayed_reg;

endmodule

