module top_module(
    count,
    Trig,
    clk,
    rst
);output [4:0] count;
wire [4:0] count;
output Trig;
reg Trig;
input clk;
input rst;

reg [4:0] count_i = 17;



always @(posedge clk, negedge rst) begin: DOWN_COUNTER_LOGIC
    if (rst) begin
        count_i <= 17;
        Trig <= 0;
    end
    else if ((count_i == 0)) begin
        Trig <= 1;
        count_i <= 17;
    end
    else begin
        count_i <= (count_i - 1);
    end
end



assign count = count_i;

endmodule

module top_module(
	input clk,
	input reset,
	output reg [3:0] q);wire feedback = q[3] ^ q[2] ^ q[1];
	always @(posedge clk) begin
		if (reset)
			q <= 4'h1;
		else
			q <= {q[2:0], feedback};
	end
endmodule

