description:
Design a module to control an 8-LED indicator that produces a moving light pattern based on a clock signal. Upon activation (nReset high), the LEDs will illuminate in a sequential pattern, cycling from left to right and then reversing direction once the end is reached, creating a back-and-forth effect. The transition between illuminated LEDs occurs every 4,000,000 clock cycles, with the current LED position stored in a 4-bit register. When the reset signal is low, the module initializes the LEDs to the first position and resets internal counters. This design effectively creates a visual status indicator for various applications.
module top_module(
	input nReset,
	input clock,


	output reg [7:0] leds
);

code:
module top_module(
	input nReset,
	input clock,


	output reg [7:0] leds
);reg [31:0] timer;
reg direction;
reg [3:0] position; 

always @ (posedge clock, negedge nReset) begin
	if (!nReset) begin
		leds <= 8'b00000001;
		timer <= 16'd0;
		direction <= 1'b1;
		position <= 4'd0;
	end else begin
		timer <= timer + 32'd1;

		if (timer >= 32'd4000000) begin
			case(position)
				4'd0:leds <= 8'b00000001;
				4'd1:leds <= 8'b00000010;
				4'd2:leds <= 8'b00000100;
				4'd3:leds <= 8'b00001000;
				4'd4:leds <= 8'b00010000;
				4'd5:leds <= 8'b00100000;
				4'd6:leds <= 8'b01000000;
				4'd7:leds <= 8'b10000000;
			endcase

			if (direction) begin
				if (position == 4'd7) begin
					position <= 4'd6;
					direction <= 1'b0;
				end else begin
					position <= position + 4'd1;
				end
			end else begin
				if (position == 4'd0) begin
					position <= 4'd1;
					direction <= 1'b1;
				end else begin
					position <= position - 4'd1;
				end
			end


			timer <= 16'd0;
		end
	end
end

endmodule

