module top_module(clk, reset, ctrl, count, overflow);input clk, reset, ctrl;
   output reg [3:0] count;
   output reg overflow;

   always @(posedge clk) begin
      if (reset) begin
         count <= 4'b0;
         overflow <= 1'b0;
      end else begin
         if (ctrl) begin
            if (count == 4'b1111) begin
               count <= 4'b0;
               overflow <= 1'b1;
            end else begin
               count <= count + 1;
               overflow <= 1'b0;
            end
         end else begin
            if (count == 4'b0000) begin
               count <= 4'b1111;
               overflow <= 1'b1;
            end else begin
               count <= count - 1;
               overflow <= 1'b0;
            end
         end
      end
   end

endmodule

