module top_module(
    input [3:0] A,
    input [3:0] B,
    input C,
    output [3:0] sum,
    output borrow
);wire [3:0] twos_comp_B;
    assign twos_comp_B = (~B) + 1;

    wire [3:0] sub_result;
    assign sub_result = A + twos_comp_B;

    assign sum = (C == 1) ? sub_result : A + B;

    assign borrow = (C == 1) ? (A < B) : (sum < A);

endmodule

module top_module(
  input clk,
  input rst,
  input [1:0] op,
  input signed [15:0] a,
  input signed [15:0] b,
  output signed [15:0] result
);reg [15:0] reg_result;

always @(posedge clk) begin
  if (rst) begin
    reg_result <= 0;
  end else begin
    case (op)
      2'b00: reg_result <= a + b;
      2'b01: reg_result <= a - b;
      2'b10: reg_result <= a * b;
      2'b11: reg_result <= a / b;
    endcase
  end
end

assign result = reg_result;

endmodule

module top_module(RESET, CLK, DEC, COUNT);input RESET, CLK, DEC;
   output [3:0] COUNT;

   parameter SEC1_MAX = 6000000;

   reg [22:0]   tmp_count;
   reg [3:0]    COUNT_TMP;
   wire         ENABLE;

   always @(posedge CLK or negedge RESET)
     begin
        if (RESET == 1'b0)
          tmp_count <= 23'h000000;
        else if (ENABLE == 1'b1)
          tmp_count <= 23'h000000;
        else
          tmp_count <= tmp_count + 23'h1;
     end

   assign ENABLE = (tmp_count == (SEC1_MAX - 1)) ? 1'b1 : 1'b0;

   always @(posedge CLK or negedge RESET)
     begin
        if (RESET == 1'b0)
          COUNT_TMP <= 4'h0;
        else if (ENABLE == 1'b1)
          if (DEC == 1'b1)
            if(COUNT_TMP == 4'h9)
              COUNT_TMP <= 4'h0;
            else
              COUNT_TMP <= COUNT_TMP + 4'h1;
          else
            if(COUNT_TMP == 4'h0)
              COUNT_TMP <= 4'h9;
            else
              COUNT_TMP <= COUNT_TMP - 4'h1;
     end 

   assign COUNT = ~COUNT_TMP;
endmodule

module fsm_mealy_100(IN, MATCH, CLK, RST);
input IN, CLK, RST;
output reg MATCH;

reg [1:0] state, next_state;

parameter S0 = 2'b00;
parameter S1 = 2'b01;
parameter S2 = 2'b10;

always @(posedge CLK or posedge RST) begin
    if (RST)
        state <= S0;
    else
        state <= next_state;
end

always @(*) begin
    case (state)
        S0: begin
            if (IN == 1)
                next_state = S1;
            else
                next_state = S0;
        end
        S1: begin
            if (IN == 0)
                next_state = S2;
            else
                next_state = S0;
        end
        S2: begin
            if (IN == 0)
                next_state = S1;
            else
                next_state = S0;
        end
        default: next_state = S0;
    endcase
end

always @(*) begin
    if (RST)
        MATCH <= 0;
    else if (state == S2 && IN == 0)
        MATCH <= 1;
    else
        MATCH <= 0;
end

endmodule

