module top_module(
    input clk,
    input load,
    input [1:0] ena,
    input [99:0] data,
    input [2:0] sel,
    input [99:0] data0,
    input [99:0] data1,
    input [99:0] data2,
    input [99:0] data3,
    input [99:0] data4,
    input [99:0] data5,
    output reg [99:0] out
);reg [99:0] mux_out;
reg [99:0] rot_out;

// 6-to-1 multiplexer
always @ (sel, data0, data1, data2, data3, data4, data5) begin
    case (sel)
        3'b000: mux_out = data0;
        3'b001: mux_out = data1;
        3'b010: mux_out = data2;
        3'b011: mux_out = data3;
        3'b100: mux_out = data4;
        3'b101: mux_out = data5;
        default: mux_out = 100'b0;
    endcase
end

// 100-bit rotator with barrel shifter architecture
always @ (posedge clk) begin
    if (load) begin
        rot_out <= data;
    end else if (ena[0]) begin
        rot_out <= {rot_out[98:0], rot_out[99]};  // Right rotation
    end else if (ena[1]) begin
        rot_out <= {rot_out[0], rot_out[99:1]};  // Left rotation
    end
end

// Final output
always @ (mux_out, rot_out) begin
    out <= mux_out ^ rot_out;
end

endmodule

