module top_module(clk, multiplicand, dividend, outclk);parameter COUNT_BITS = 32;
  input clk;
  input [COUNT_BITS - 1:0] multiplicand, dividend;
  output outclk;

  reg [COUNT_BITS - 1:0] counter = 0;
  reg outclk = 0;

  always @(clk) begin
    if (clk == 1) begin
      counter = counter + multiplicand;
      if (counter >= dividend) begin
        counter = counter - dividend;
        outclk = 1;
      end
    end else begin
      outclk = 0;
    end
  end
endmodule

module top_module(
    input   aclr,
    input   clk_en,
    input   clock,
    input   [54:0] data,
    input   [5:0]  distance,
    output  [54:0] result
    );reg [54:0] pipe_wl1c;
    wire [31:0] pad_w;
    wire [384:0] sbit_w;
    wire [5:0] sel_w;
