Design a clock divider circuit that takes a 50 MHz input clock (CLOCK_50) and generates a 25 MHz output clock (CLOCK_25). This module toggles a register on every rising edge of the input clock, effectively dividing the frequency by two to provide a lower frequency clock for applications such as synchronization or timing in digital designs.
module top_module(
    CLOCK_50,
    CLOCK_25
);

code:
module top_module(
    CLOCK_50,
    CLOCK_25
);input CLOCK_50;
    output CLOCK_25;
    reg clk = 0;

    always @(posedge CLOCK_50) begin
        clk <= ~clk;
    end

    assign CLOCK_25 = clk;
endmodule

