   output [31:0]     hatch_address;
   input 	     clk, rst_b;
   input [47:0]      hatch_instruction;



   reg [31:0] 	 next_pc;



   assign hatch_address = { (kill_4a ? branch_target_4a : next_pc) >> 1, 1'b0 };



